ACS_APP_VERSION_t ANALOG_CONVERTER_EVADC_GetAppVersion(void)
{
  ACS_APP_VERSION_t version;

  version.major = ANALOG_CONVERTER_EVADC_MAJOR_VERSION;
  version.minor = ANALOG_CONVERTER_EVADC_MINOR_VERSION;
  version.patch = ANALOG_CONVERTER_EVADC_PATCH_VERSION;

  return version;
}

ANALOG_CONVERTER_EVADC_STATUS_t ANALOG_CONVERTER_EVADC_Init(ANALOG_CONVERTER_EVADC_t* handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (handle->app_config != NULL)));

  ANALOG_CONVERTER_EVADC_STATUS_t status = ANALOG_CONVERTER_EVADC_STATUS_SUCCESS;

  if (!handle->app_is_initialized)
  {
    if (EVADC_GENERIC_Init(handle->evadc_generic_handle) == EVADC_GENERIC_STATUS_SUCCESS)
    {
      /* Assign array members of the APP Struct and APP Configuration struct */
      handle->app_config->init_arrays_func_ptr();

      /* The config struct needs to have the address of the module handle */
      handle->app_config->group_config->module = &handle->evadc_generic_handle->app_config->evadcModuleHandle;

      /* Perform group configuration */
      if (IfxEvadc_Adc_initGroup(handle->group, handle->app_config->group_config) == IfxEvadc_Status_noError)
      {
        /* Perform channels configuration */
        for (uint16 idx = 0; idx < handle->number_of_channels; idx++)
        {
          if (handle->app_config->port_pin_config[idx].port != NULL_PTR)
          {
            IfxPort_setPinFunctionMode(handle->app_config->port_pin_config[idx].port,
                                       handle->app_config->port_pin_config[idx].pinIndex,
                                       IfxPort_PinFunctionMode_analog);
          }
          IfxEvadc_Adc_initChannel(&(handle->channels[idx]), &(handle->app_config->channel_configs[idx]));
        }

        /*
         * Enable ISR for channels with result event enabled
         * This should be called only after groups and channels are configured
         */
        if (handle->app_config->init_events_func_ptr != NULL_PTR)
        {
          handle->app_config->init_events_func_ptr();
        }

        /* Check if it is necessary to init required APPs required by ANALOG_CONVERTER_EVADC internally */
        if (handle->app_config->init_required_apps_func_ptr != NULL_PTR)
        {
          status = handle->app_config->init_required_apps_func_ptr();
        }

        if (status == ANALOG_CONVERTER_EVADC_STATUS_SUCCESS)
        {
          /* If start conversion after initialization is set, explicitly start conversion right before ending the init function */
          if (handle->app_config->start_conversion_after_init)
          {
            status = ANALOG_CONVERTER_EVADC_StartConversion(handle);
          }

          if (status == ANALOG_CONVERTER_EVADC_STATUS_SUCCESS)
          {
            handle->app_is_initialized = TRUE;
          }
        }
      }
      else
      {
        status = ANALOG_CONVERTER_EVADC_STATUS_FAILURE;
      }
    }
  }

  return status;
}

ANALOG_CONVERTER_EVADC_STATUS_t ANALOG_CONVERTER_EVADC_StartConversion(ANALOG_CONVERTER_EVADC_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (handle->app_config != NULL)));

  ANALOG_CONVERTER_EVADC_STATUS_t status = ANALOG_CONVERTER_EVADC_STATUS_SUCCESS;

  /* Add channel to queue with refill option enabled */
  for (uint16 idx = 0; idx < handle->number_of_channels; idx++)
  {
    /* Check if queue is already full */
    if (IfxEvadc_getQueueStatus(handle->group->group, IfxEvadc_RequestSource_queue0) == IfxEvadc_Status_noError)
    {
      IfxEvadc_Adc_addToQueue(&(handle->channels[idx]), IfxEvadc_RequestSource_queue0, handle->app_config->queue_flag);
    }
    else
    {
      status = ANALOG_CONVERTER_EVADC_STATUS_FAILURE;
      break;
    }
  }
  if (status == ANALOG_CONVERTER_EVADC_STATUS_SUCCESS)
  {
    /* Start the queue if external trigger is NOT enabled (QMR and QINR registers) */
    if ((handle->app_config->queue_flag & (1 << IFX_EVADC_G_Q_QINR_EXTR_OFF)) == 0) {
      IfxEvadc_Adc_startQueue(handle->group, IfxEvadc_RequestSource_queue0);
    }
  }

  return status;
}

ANALOG_CONVERTER_EVADC_STATUS_t ANALOG_CONVERTER_EVADC_CaptureResults(ANALOG_CONVERTER_EVADC_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));

  ANALOG_CONVERTER_EVADC_STATUS_t status = ANALOG_CONVERTER_EVADC_STATUS_SUCCESS;
  for (uint8 i = 0; i < handle->number_of_channels; i++)
  {
    /* Read the result of the channel */
    Ifx_EVADC_G_RES conversionResult = IfxEvadc_Adc_getResult(&(handle->channels[i]));

    /* No valid result */
    if (!conversionResult.B.VF)
    {
      status = ANALOG_CONVERTER_EVADC_STATUS_FAILURE;
      break;
    }

    /* Store result */
    handle->results[i] = conversionResult;
  }
  return status;
}

ANALOG_CONVERTER_EVADC_STATUS_t ANALOG_CONVERTER_EVADC_CaptureResult(ANALOG_CONVERTER_EVADC_t *handle, int channel_index)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (channel_index >= handle->number_of_channels)));
  ANALOG_CONVERTER_EVADC_STATUS_t status = ANALOG_CONVERTER_EVADC_STATUS_SUCCESS;

  /* Read the result of the selected channel */
  Ifx_EVADC_G_RES conversionResult = IfxEvadc_Adc_getResult(&(handle->channels[channel_index]));

  /* No valid result */
  if (!conversionResult.B.VF)
  {
    status = ANALOG_CONVERTER_EVADC_STATUS_FAILURE;
  }
  else
  {
    /* Store result */
    handle->results[channel_index] = conversionResult;
  }
  return status;
}

uint32 ANALOG_CONVERTER_EVADC_GetChannelResultU32(ANALOG_CONVERTER_EVADC_t *handle, int channel_index)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (channel_index >= handle->number_of_channels)));

  return handle->results[channel_index].B.RESULT;
}

void ANALOG_CONVERTER_EVADC_StopConversion(ANALOG_CONVERTER_EVADC_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));

  IfxEvadc_Adc_clearQueue(handle->group, IfxEvadc_RequestSource_queue0);
}

